-- ES/DE/FR translations for the rest of Poland's deep-dive content.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (KSeF)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los detalles de la API de KSeF 2.0, los requisitos de autenticación y la modificación pendiente del artículo 106ni siguen evolucionando — confirme los requisitos actuales directamente en el portal KSeF del Ministerio de Finanzas antes de construir una integración.', 'KSeF ya se ha reconstruido una vez — Polonia pausó una versión anterior después de que una auditoría técnica determinara que la arquitectura necesitaba reforzarse. KSeF 2.0 es la versión que realmente entró en funcionamiento.', 'FA(3) es la tercera generación del esquema nacional de Polonia — cada revisión ha reforzado la validación y añadido más detalle estructurado que la anterior.', 'KSeF es un auténtico modelo de compensación: el comprador recupera la factura del sistema central en lugar de recibirla directamente del vendedor.', 'La configuración del acceso es un proceso único centrado en un único formulario de autorización y su elección de credencial de autenticación.', 'El régimen de sanciones de Polonia está entre los más estrictos de Europa sobre el papel — pero un periodo de gracia de un año completo y una aclaración legislativa planificada suavizan considerablemente el panorama.' FROM countries WHERE name_en = 'Poland';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (KSeF)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Details zur KSeF-2.0-API, Authentifizierungsanforderungen und die anstehende Änderung von Artikel 106ni entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt auf dem KSeF-Portal des Finanzministeriums, bevor Sie eine Integration aufbauen.', 'KSeF wurde bereits einmal neu aufgebaut — Polen pausierte eine frühere Version, nachdem eine technische Prüfung ergab, dass die Architektur gestärkt werden musste. KSeF 2.0 ist die Version, die tatsächlich live ging.', 'FA(3) ist die dritte Generation von Polens nationalem Schema — jede Überarbeitung hat die Validierung verschärft und mehr strukturierte Details hinzugefügt als die vorherige.', 'KSeF ist ein echtes Clearing-Modell: Der Käufer ruft die Rechnung aus dem zentralen System ab, statt sie direkt vom Verkäufer zu erhalten.', 'Die Zugangseinrichtung ist ein einmaliger Prozess, der sich auf ein einziges Berechtigungsformular und Ihre Wahl der Authentifizierungs-Berechtigung konzentriert.', 'Polens Sanktionsregime gehört auf dem Papier zu den strengsten in Europa — doch eine einjährige Übergangsfrist und eine geplante gesetzliche Klarstellung mildern das Bild erheblich ab.' FROM countries WHERE name_en = 'Poland';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (KSeF)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les détails de l''API KSeF 2.0, les exigences d''authentification et la modification en attente de l''article 106ni continuent d''évoluer — confirmez les exigences actuelles directement sur le portail KSeF du ministère des Finances avant de construire une intégration.', 'KSeF a déjà été reconstruit une fois — la Pologne a suspendu une version antérieure après qu''un audit technique a révélé que l''architecture devait être renforcée. KSeF 2.0 est la version réellement entrée en service.', 'FA(3) est la troisième génération du schéma national de la Pologne — chaque révision a renforcé la validation et ajouté davantage de détails structurés que la précédente.', 'KSeF est un véritable modèle de contrôle : l''acheteur récupère la facture depuis le système central plutôt que de la recevoir directement du vendeur.', 'La configuration de l''accès est un processus unique centré sur un formulaire d''autorisation unique et votre choix d''identifiant d''authentification.', 'Le régime de sanctions polonais est parmi les plus stricts d''Europe sur le papier — mais une période de grâce d''un an complet et une clarification législative prévue adoucissent considérablement le tableau.' FROM countries WHERE name_en = 'Poland';

