INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Esquema', '[["Versión actual", "FA(3) (sustituyó a FA(2), 1 de febrero de 2026)"], ["Alineación", "Modelo semántico EN 16931, convenciones Peppol BIS"], ["Novedades en FA(3)", "Nuevos códigos de tipo de IVA, soporte de adjuntos, fechas desde 1990"]]', 'FA(3) se configuró directamente mediante consultas fiscales con emprendedores, contables, auditores y proveedores de TI — el soporte de adjuntos en particular fue una respuesta directa a los comentarios de que FA(2) era demasiado rígido para escenarios de facturación reales.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Schema';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Schema', '[["Aktuelle Version", "FA(3) (ersetzte FA(2), 1. Februar 2026)"], ["Ausrichtung", "EN-16931-semantisches Modell, Peppol-BIS-Konventionen"], ["Neu in FA(3)", "Neue USt-Satzcodes, Anhang-Unterstützung, Daten ab 1990"]]', 'FA(3) wurde direkt durch steuerliche Konsultationen mit Unternehmern, Steuerberatern, Prüfern und IT-Anbietern geformt — die Anhang-Unterstützung war insbesondere eine direkte Reaktion auf Rückmeldungen, dass FA(2) für reale Rechnungsstellungsszenarien zu starr war.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Schema';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Schéma', '[["Version actuelle", "FA(3) (a remplacé FA(2), 1er février 2026)"], ["Alignement", "Modèle sémantique EN 16931, conventions Peppol BIS"], ["Nouveautés dans FA(3)", "Nouveaux codes de taux de TVA, prise en charge des pièces jointes, dates depuis 1990"]]', 'FA(3) a été façonné directement par des consultations fiscales avec entrepreneurs, comptables, auditeurs et fournisseurs informatiques — la prise en charge des pièces jointes en particulier a été une réponse directe aux retours indiquant que FA(2) était trop rigide pour des scénarios de facturation réels.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Schema';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Identificadores", "NIP del proveedor y del cliente"], ["Detalle de la transacción", "Líneas detalladas, tipos e importes de IVA, totales, moneda"], ["Observaciones legales", "Inversión del sujeto pasivo y otros indicadores requeridos"], ["Firma digital", "No requerida de los proveedores"]]', 'Los proveedores no aplican su propia firma cualificada — el propio proceso de compensación de KSeF (validación, sellado y asignación del número de referencia) es lo que otorga fuerza legal a la factura, de manera similar en espíritu al modelo SDI de Italia.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Mandatory content';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalt', '[["Kennungen", "NIP von Lieferant & Kunde"], ["Transaktionsdetails", "Einzelposten, USt-Sätze und -Beträge, Summen, Währung"], ["Rechtliche Hinweise", "Reverse-Charge und andere erforderliche Kennzeichen"], ["Digitale Signatur", "Von Lieferanten nicht erforderlich"]]', 'Lieferanten bringen keine eigene qualifizierte Signatur an — der eigene Clearing-Prozess von KSeF (Validierung, Versiegelung und Zuweisung der Referenznummer) verleiht der Rechnung Rechtskraft, ähnlich im Grundgedanken wie Italiens SDI-Modell.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Mandatory content';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Identifiants", "NIP du fournisseur et du client"], ["Détail de la transaction", "Lignes détaillées, taux et montants de TVA, totaux, devise"], ["Mentions légales", "Autoliquidation et autres indicateurs requis"], ["Signature numérique", "Non requise des fournisseurs"]]', 'Les fournisseurs n''apposent pas leur propre signature qualifiée — c''est le processus de contrôle propre à KSeF (validation, scellement et attribution du numéro de référence) qui confère force légale à la facture, dans un esprit similaire au modèle SDI italien.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Mandatory content';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Resultado de la compensación', '[["Número de referencia", "Número KSeF único, asignado al validar"], ["Recibo", "Confirmación UPO (Urzędowe Poświadczenie Odbioru)"], ["Verificación", "Código QR que enlaza al sistema central"]]', 'Una factura sin un número KSeF válido no es válida a efectos fiscales — esta es la diferencia práctica más marcada respecto a modelos descentralizados como el de Alemania, donde el propio archivo tiene fuerza legal sin un paso de compensación central.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Clearance output';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Clearing-Ausgabe', '[["Referenznummer", "Eindeutige KSeF-Nummer, bei Validierung vergeben"], ["Beleg", "UPO-Bestätigung (Urzędowe Poświadczenie Odbioru)"], ["Verifizierung", "QR-Code mit Verknüpfung zum Zentralsystem"]]', 'Eine Rechnung ohne gültige KSeF-Nummer ist steuerlich nicht gültig — dies ist der schärfste praktische Unterschied zu dezentralisierten Modellen wie dem Deutschlands, wo die Datei selbst ohne zentralen Clearing-Schritt Rechtskraft trägt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Clearance output';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Résultat du contrôle', '[["Numéro de référence", "Numéro KSeF unique, attribué lors de la validation"], ["Accusé de réception", "Confirmation UPO (Urzędowe Poświadczenie Odbioru)"], ["Vérification", "Code QR renvoyant au système central"]]', 'Une facture sans numéro KSeF valide n''est pas valable à des fins fiscales — c''est la différence pratique la plus nette par rapport aux modèles décentralisés comme celui de l''Allemagne, où le fichier lui-même a force légale sans étape de contrôle central.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Clearance output';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Conservación central", "10 años desde el cierre del ejercicio de emisión"], ["Conservación estándar en PL", "5 años (KSeF la duplica)"]]', 'Dado que KSeF almacena centralmente cada factura validada durante 10 años, las empresas no necesitan archivar de forma independiente los archivos XML de facturas para fines de cumplimiento — una simplificación operativa genuina en comparación con los regímenes descentralizados.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Zentrale Aufbewahrung", "10 Jahre ab Jahresende der Ausstellung"], ["Standard-PL-Aufbewahrung", "5 Jahre (KSeF verdoppelt dies)"]]', 'Da KSeF jede validierte Rechnung 10 Jahre zentral speichert, müssen Unternehmen Rechnungs-XML-Dateien für Compliance-Zwecke nicht eigenständig archivieren — eine echte betriebliche Vereinfachung im Vergleich zu dezentralisierten Regimen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Conservation centrale", "10 ans à partir de la fin d''année d''émission"], ["Conservation standard PL", "5 ans (KSeF double ce délai)"]]', 'Comme KSeF stocke chaque facture validée de manière centrale pendant 10 ans, les entreprises n''ont pas besoin d''archiver indépendamment les fichiers XML de factures à des fins de conformité — une véritable simplification opérationnelle par rapport aux régimes décentralisés.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'API', '[["Especificación", "OpenAPI 3.0.4"], ["SDKs", ".NET y Java, con código de ejemplo"], ["Modos de envío", "Interactivo y por lotes"]]', 'Realice pruebas exhaustivas en el entorno de pruebas antes de conectarse a producción — la documentación de la API incluye referencias completas de endpoints, parámetros y códigos de respuesta específicamente para apoyar esto.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'API';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'API', '[["Spezifikation", "OpenAPI 3.0.4"], ["SDKs", ".NET und Java, mit Beispielcode"], ["Übermittlungsmodi", "Interaktiv und im Batch"]]', 'Testen Sie gründlich in der Sandbox-Umgebung, bevor Sie sich mit der Produktion verbinden — die API-Dokumentation enthält vollständige Endpunkt-, Parameter- und Antwortcode-Referenzen speziell zu diesem Zweck.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'API';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'API', '[["Spécification", "OpenAPI 3.0.4"], ["SDK", ".NET et Java, avec exemples de code"], ["Modes de soumission", "Interactif et par lots"]]', 'Testez minutieusement dans l''environnement bac à sable avant de vous connecter à la production — la documentation de l''API inclut des références complètes de points de terminaison, paramètres et codes de réponse spécifiquement à cet effet.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'API';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Métodos de autenticación', '[["Sello electrónico cualificado", "Que contenga el NIP del contribuyente"], ["Certificado KSeF", "A través del Módulo de Certificados y Autorizaciones (MCU)"], ["Token", "Disponible solo hasta finales de 2026"], ["Perfil de Confianza", "Eliminado desde el 1 de abril de 2026"]]', 'Planifique su enfoque de autenticación a largo plazo en torno a sellos cualificados o certificados KSeF — tanto los tokens como la vía del Perfil de Confianza se están eliminando gradualmente en plazos diferentes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'Authentication methods';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Authentifizierungsmethoden', '[["Qualifiziertes elektronisches Siegel", "Mit der NIP des Steuerzahlers"], ["KSeF-Zertifikat", "Über das Modul für Zertifikate und Berechtigungen (MCU)"], ["Token", "Nur bis Ende 2026 verfügbar"], ["Trusted Profile", "Ab 1. April 2026 entfernt"]]', 'Planen Sie Ihren langfristigen Authentifizierungsansatz um qualifizierte Siegel oder KSeF-Zertifikate — sowohl Token als auch der Trusted-Profile-Weg werden auf unterschiedlichen Zeitplänen ausgemustert.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'Authentication methods';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Méthodes d''authentification', '[["Cachet électronique qualifié", "Contenant le NIP du contribuable"], ["Certificat KSeF", "Via le module des certificats et autorisations (MCU)"], ["Jeton", "Disponible jusqu''à fin 2026 seulement"], ["Profil de confiance", "Supprimé à partir du 1er avril 2026"]]', 'Planifiez votre approche d''authentification à long terme autour des cachets qualifiés ou des certificats KSeF — le jeton et la voie du profil de confiance sont tous deux progressivement supprimés selon des calendriers différents.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'Authentication methods';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Flujo del comprador', '[["Modelo de entrega", "Recuperación desde KSeF, no envío directo"], ["Destinatarios con NIP nacional", "Reciben exclusivamente a través de KSeF tras la compensación"], ["Destinatarios sin KSeF (entrega sin conexión)", "Requieren códigos QR dobles antes del envío"]]', 'Este modelo de "el comprador recupera en lugar de recibir" es la diferencia estructural clave respecto a los países basados en Peppol — no hay un paso de "entrega" en el sentido convencional una vez que una factura es compensada por KSeF.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'Buyer workflow';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Käufer-Workflow', '[["Zustellmodell", "Abruf aus KSeF, kein direkter Versand"], ["Inländische NIP-Empfänger", "Empfangen ausschließlich über KSeF nach Freigabe"], ["Nicht-KSeF-Empfänger (Offline-Zustellung)", "Benötigen doppelte QR-Codes vor der Einreichung"]]', 'Dieses Modell des "Abrufens statt Empfangens" durch den Käufer ist der zentrale strukturelle Unterschied zu Peppol-basierten Ländern — es gibt keinen "Zustell"-Schritt im herkömmlichen Sinne, sobald eine Rechnung KSeF durchlaufen hat.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'Buyer workflow';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Flux de travail de l''acheteur', '[["Modèle de livraison", "Récupération depuis KSeF, pas d''envoi direct"], ["Destinataires NIP domestiques", "Reçoivent exclusivement via KSeF après contrôle"], ["Destinataires non-KSeF (livraison hors ligne)", "Nécessitent des doubles codes QR avant soumission"]]', 'Ce modèle où « l''acheteur récupère plutôt qu''il ne reçoit » est la différence structurelle clé par rapport aux pays basés sur Peppol — il n''y a pas d''étape de « livraison » au sens conventionnel une fois qu''une facture a été validée par KSeF.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'scope_transmission' AND dct.title = 'Buyer workflow';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🕊️ Periodo de gracia completo de 2026', NULL, NULL, 'No se aplican sanciones financieras por errores de KSeF durante todo 2026, independientemente de cuándo caiga la fecha de inicio obligatoria de una empresa determinada — la aplicación real comienza el 1 de enero de 2027, no antes.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '🕊️ Full 2026 grace period';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🕊️ Vollständige Übergangsfrist 2026', NULL, NULL, 'Während des gesamten Jahres 2026 gelten keine finanziellen Sanktionen für KSeF-Fehler, unabhängig davon, wann das verpflichtende Startdatum eines bestimmten Unternehmens liegt — die tatsächliche Durchsetzung beginnt erst am 1. Januar 2027.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '🕊️ Full 2026 grace period';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🕊️ Période de grâce complète 2026', NULL, NULL, 'Aucune sanction financière ne s''applique pour les erreurs KSeF tout au long de 2026, quelle que soit la date de démarrage obligatoire d''une entreprise donnée — l''application effective ne commence réellement que le 1er janvier 2027.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '🕊️ Full 2026 grace period';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Corrección legislativa planificada', NULL, NULL, 'El Ministerio de Finanzas ha reconocido una "referencia redundante" en el artículo 106ni y planea modificar la Ley del IVA antes del plazo de enero de 2027, de modo que las sanciones se apliquen solo a la evasión deliberada de KSeF — no a errores incidentales durante el funcionamiento normal del sistema.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Planned legislative fix';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Geplante gesetzliche Korrektur', NULL, NULL, 'Das Finanzministerium hat einen "überflüssigen Verweis" in Artikel 106ni eingeräumt und plant, das Umsatzsteuergesetz vor der Frist im Januar 2027 zu ändern, sodass Sanktionen nur bei vorsätzlicher KSeF-Umgehung gelten — nicht bei versehentlichen Fehlern in einem funktionierenden System.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Planned legislative fix';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Correctif législatif prévu', NULL, NULL, 'Le ministère des Finances a reconnu une « référence redondante » dans l''article 106ni et prévoit de modifier la loi sur la TVA avant l''échéance de janvier 2027, afin que les sanctions ne s''appliquent qu''au contournement délibéré de KSeF — pas aux erreurs accidentelles dans un système fonctionnel.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Planned legislative fix';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Excepciones estrechas y continuas', NULL, NULL, 'Los contribuyentes "digitalmente excluidos" — aquellos genuinamente incapaces de acceder a la infraestructura digital, con transacciones inferiores a 450 PLN por factura y 10.000 PLN de ventas mensuales totales — conservan una excepción incluso después de enero de 2027.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '🧾 Narrow ongoing exceptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Enge fortlaufende Ausnahmen', NULL, NULL, '"Digital ausgeschlossene" Steuerzahler — jene, die genuin keinen Zugang zu digitaler Infrastruktur haben, mit Transaktionen unter 450 PLN pro Rechnung und 10.000 PLN monatlichem Gesamtumsatz — behalten auch nach Januar 2027 eine Ausnahme.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '🧾 Narrow ongoing exceptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Exceptions restreintes persistantes', NULL, NULL, 'Les contribuables « numériquement exclus » — ceux véritablement incapables d''accéder à l''infrastructure numérique, avec des transactions inférieures à 450 PLN par facture et 10 000 PLN de ventes mensuelles totales — conservent une exception même après janvier 2027.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Poland' AND dc.section = 'penalties_related' AND dct.title = '🧾 Narrow ongoing exceptions';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Evalúe la compatibilidad de su sistema con FA(3) y la API', 'Compruebe su software de facturación o ERP frente a la estructura lógica FA(3) y la documentación de la API de KSeF 2.0, o planifique usar las herramientas gratuitas del Ministerio si no tiene capacidad de desarrollo interna.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Assess your system''s FA(3) and API compatibility';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die FA(3)- und API-Kompatibilität Ihres Systems', 'Prüfen Sie Ihre Rechnungs- oder ERP-Software anhand der logischen FA(3)-Struktur und der KSeF-2.0-API-Dokumentation, oder planen Sie die Nutzung der kostenlosen Tools des Ministeriums, falls Sie über keine eigene Entwicklungskapazität verfügen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Assess your system''s FA(3) and API compatibility';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Évaluez la compatibilité FA(3) et API de votre système', 'Vérifiez votre logiciel de facturation ou ERP par rapport à la structure logique FA(3) et à la documentation de l''API KSeF 2.0, ou prévoyez d''utiliser les outils gratuits du ministère si vous ne disposez pas de capacité de développement interne.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Assess your system''s FA(3) and API compatibility';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Presente el formulario de autorización ZAW-FA', 'Este designa a la persona autorizada para operar KSeF en nombre de su entidad. No es necesario si posee un sello electrónico cualificado que contenga su NIP — en ese caso puede usar KSeF directamente. La persona designada en ZAW-FA puede entonces otorgar más autorizaciones a otros directamente dentro de la plataforma.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'File the ZAW-FA authorisation form';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Reichen Sie das ZAW-FA-Berechtigungsformular ein', 'Dies benennt die Person, die berechtigt ist, KSeF im Namen Ihrer Einheit zu bedienen. Es ist nicht erforderlich, wenn Sie ein qualifiziertes elektronisches Siegel mit Ihrer NIP besitzen — in diesem Fall können Sie KSeF direkt nutzen. Die in ZAW-FA genannte Person kann dann direkt innerhalb der Plattform weitere Berechtigungen an andere vergeben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'File the ZAW-FA authorisation form';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déposez le formulaire d''autorisation ZAW-FA', 'Celui-ci désigne la personne autorisée à utiliser KSeF au nom de votre entité. Ce n''est pas requis si vous détenez un cachet électronique qualifié contenant votre NIP — dans ce cas, vous pouvez utiliser KSeF directement. La personne nommée dans le ZAW-FA peut ensuite accorder d''autres autorisations à d''autres personnes directement au sein de la plateforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'File the ZAW-FA authorisation form';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga su credencial de autenticación', 'Solicite un certificado KSeF a través del Módulo de Certificados y Autorizaciones, o use un token durante el periodo transitorio (disponible solo hasta finales de 2026). Toda persona autorizada necesita un NIP o PESEL, o una firma electrónica cualificada si no tiene ninguno de los dos.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Obtain your authentication credential';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie sich Ihre Authentifizierungs-Berechtigung', 'Beantragen Sie ein KSeF-Zertifikat über das Modul für Zertifikate und Berechtigungen, oder nutzen Sie während der Übergangszeit ein Token (nur bis Ende 2026 verfügbar). Jede berechtigte Person benötigt eine NIP oder PESEL, oder eine qualifizierte elektronische Signatur, falls sie über keines von beidem verfügt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Obtain your authentication credential';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez votre identifiant d''authentification', 'Demandez un certificat KSeF via le module des certificats et autorisations, ou utilisez un jeton pendant la période transitoire (disponible jusqu''à fin 2026 seulement). Chaque personne autorisée a besoin d''un NIP ou PESEL, ou d''une signature électronique qualifiée si elle n''a ni l''un ni l''autre.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Obtain your authentication credential';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe en el entorno de pruebas antes de pasar a producción', 'Use el entorno de pruebas de KSeF 2.0 para probar el envío de facturas, la recuperación de recibos y la gestión de errores — aquí es donde surgen la mayoría de los problemas de integración, mucho antes de que lleguen a producción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Test in the sandbox before going live';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie in der Sandbox, bevor Sie live gehen', 'Nutzen Sie die KSeF-2.0-Testumgebung, um Rechnungseinreichung, Belegabruf und Fehlerbehandlung zu erproben — hier treten die meisten Integrationsprobleme auf, lange bevor sie die Produktion erreichen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Test in the sandbox before going live';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez dans le bac à sable avant la mise en production', 'Utilisez l''environnement de test KSeF 2.0 pour tester la soumission des factures, la récupération des accusés de réception et la gestion des erreurs — c''est là que la plupart des problèmes d''intégration apparaissent, bien avant d''atteindre la production.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Test in the sandbox before going live';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure la delegación para proveedores externos', 'Si un contable o un servicio externo gestiona la facturación por usted, configure explícitamente sus reglas de autorización y delegación en lugar de compartir sus propias credenciales.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Set up delegation for third-party providers';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie die Delegation für externe Anbieter ein', 'Wenn ein Steuerberater oder ein externer Dienst die Rechnungsstellung für Sie übernimmt, konfigurieren Sie dessen Berechtigungs- und Delegationsregeln ausdrücklich, statt Ihre eigenen Zugangsdaten weiterzugeben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Set up delegation for third-party providers';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place la délégation pour les prestataires tiers', 'Si un comptable ou un service externe gère la facturation pour vous, configurez explicitement ses règles d''autorisation et de délégation plutôt que de partager vos propres identifiants.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Set up delegation for third-party providers';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Integre la gestión de offline24 en su flujo de trabajo', 'Implemente la capacidad de emitir facturas estructuradas fuera de KSeF durante una interrupción, genere el código QR requerido y envíe a KSeF a más tardar el siguiente día hábil.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Build offline24 handling into your pipeline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Integrieren Sie die Offline24-Behandlung in Ihre Pipeline', 'Implementieren Sie die Fähigkeit, strukturierte Rechnungen während eines Ausfalls außerhalb von KSeF auszustellen, den erforderlichen QR-Code zu erzeugen und spätestens am nächsten Werktag an KSeF zu übermitteln.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Build offline24 handling into your pipeline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez la gestion offline24 dans votre pipeline', 'Mettez en œuvre la capacité d''émettre des factures structurées en dehors de KSeF pendant une interruption, de générer le code QR requis et de soumettre à KSeF au plus tard le jour ouvré suivant.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Poland' AND dst.title = 'Build offline24 handling into your pipeline';

