INSERT OR IGNORE INTO deep_dive_lifecycle_intro_translations (country_id, lang, title, intro_text) SELECT id, 'es', 'Modos sin conexión y códigos QR', 'Existen cuatro modos sin conexión para cuando KSeF en sí no está disponible o resulta inaccesible. Las facturas emitidas sin conexión o en modo de fallo necesitan un código QR para su verificación, y deben enviarse a KSeF antes del siguiente día hábil. Los titulares de NIP nacional ya no necesitan un código QR en la propia impresión — recuperan la factura legalmente válida directamente a través de KSeF, excepto en modo de fallo.' FROM countries WHERE name_en = 'Poland';
INSERT OR IGNORE INTO deep_dive_lifecycle_intro_translations (country_id, lang, title, intro_text) SELECT id, 'de', 'Offline-Modi & QR-Codes', 'Es gibt vier Offline-Modi für den Fall, dass KSeF selbst nicht verfügbar oder nicht erreichbar ist. Offline oder im Ausfallmodus ausgestellte Rechnungen benötigen zur Verifizierung einen QR-Code und müssen spätestens am nächsten Werktag an KSeF übermittelt werden. Inländische NIP-Inhaber benötigen keinen QR-Code mehr auf dem Ausdruck selbst — sie rufen die rechtsgültige Rechnung direkt über KSeF ab, außer im Ausfallmodus.' FROM countries WHERE name_en = 'Poland';
INSERT OR IGNORE INTO deep_dive_lifecycle_intro_translations (country_id, lang, title, intro_text) SELECT id, 'fr', 'Modes hors ligne et codes QR', 'Il existe quatre modes hors ligne pour les cas où KSeF lui-même est indisponible ou inaccessible. Les factures émises hors ligne ou en mode de défaillance nécessitent un code QR pour vérification, et doivent être soumises à KSeF au plus tard le jour ouvré suivant. Les détenteurs de NIP domestiques n''ont plus besoin d''un code QR sur l''impression elle-même — ils récupèrent la facture légalement valable directement via KSeF, sauf en mode de défaillance.' FROM countries WHERE name_en = 'Poland';
